package com.flowfolio.feature.reader.riffle

import android.content.Context
import android.media.AudioAttributes
import android.media.AudioManager
import android.media.SoundPool
import android.os.SystemClock
import kotlin.random.Random

/**
 * The scrubber's paper sounds (ADR-0023), generated by `tools/sounds/make_paper_sounds.py`: a flick as pages pass, a
 * thump at a chapter start, a whoosh for each landing sheet. Silent in silent and vibrate ringer modes; flicks play at
 * most one every [MIN_GAP_MS], each at a slightly different pitch. [release] when the reader closes.
 */
class RiffleSounds(context: Context) {
    private val audio = context.getSystemService(AudioManager::class.java)
    private val pool = SoundPool.Builder()
        .setMaxStreams(MAX_STREAMS)
        .setAudioAttributes(
            AudioAttributes.Builder()
                .setUsage(AudioAttributes.USAGE_ASSISTANCE_SONIFICATION)
                .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                .build()
        )
        .build()
    private val flick = pool.load(context, R.raw.riffle_flick, 1)
    private val thump = pool.load(context, R.raw.riffle_thump, 1)
    private val whoosh = pool.load(context, R.raw.riffle_whoosh, 1)
    private val random = Random(SystemClock.uptimeMillis())
    private var lastFlick = 0L

    /** The sounds for one step of a drag: flicks for the pages passed, a thump at a chapter start. */
    fun play(feedback: RiffleFeedback) {
        if (!audible()) return
        if (feedback.thump) {
            pool.play(thump, THUMP_VOLUME, THUMP_VOLUME, 1, 0, 1f)
        } else if (feedback.flicks > 0) {
            flick(FLICK_VOLUME * (MIN_LOUDNESS + random.nextFloat() * LOUDNESS_RANGE))
        }
    }

    /** One landing sheet turning; [strength] below 1 for the quick sheets of a long turn. */
    fun whoosh(strength: Float = 1f) {
        if (!audible()) return
        val volume = (WHOOSH_VOLUME * strength).coerceIn(0f, 1f)
        pool.play(whoosh, volume, volume, 1, 0, 1f)
    }

    private fun flick(volume: Float) {
        val now = SystemClock.uptimeMillis()
        if (now - lastFlick < MIN_GAP_MS) return
        lastFlick = now
        val rate = MIN_RATE + random.nextFloat() * (MAX_RATE - MIN_RATE)
        pool.play(flick, volume, volume, 0, 0, rate)
    }

    private fun audible() = audio?.ringerMode == AudioManager.RINGER_MODE_NORMAL

    fun release() = pool.release()

    private companion object {
        const val MAX_STREAMS = 4
        const val MIN_GAP_MS = 18L
        const val MIN_RATE = 0.85f
        const val MAX_RATE = 1.25f
        const val FLICK_VOLUME = 0.5f

        /** Each flick is 0.6 to 1.2 times as loud, like the mock's. */
        const val MIN_LOUDNESS = 0.6f
        const val LOUDNESS_RANGE = 0.6f
        const val THUMP_VOLUME = 0.7f
        const val WHOOSH_VOLUME = 0.6f
    }
}
